gemeinschaft_aufhebungsanteil <- function(gemeinschaftlicher_erloes=NULL,zu_berichtigende_gemeinsame_schulden=NULL,teilhaberquote=NULL,gemeinschaftsbezogene_teilhaberschuld=NULL,einordnungsnachweis=NULL) {
 erloes <- .geld(gemeinschaftlicher_erloes); gemeinsam <- .geld(zu_berichtigende_gemeinsame_schulden); quote <- .geld(teilhaberquote); eigen <- .geld(gemeinschaftsbezogene_teilhaberschuld)
 .text(einordnungsnachweis,'einordnungsnachweis')
 if(.vergleichen(quote,.bruch(1))>0) .fehler('teilhaberquote','Teilhaberquote darf eins nicht \u00fcbersteigen.')
 positiv <- function(x) if(.vergleichen(x,.bruch(0))>0) x else .bruch(0)
 masse <- positiv(.subtrahieren(erloes,gemeinsam)); anteil <- .multiplizieren(masse,quote); berichtigung <- if(.vergleichen(anteil,eigen)<0) anteil else eigen
 wert <- list(verteilbare_erloesmasse=.bruchteile(masse),anteil_vor_teilhaberschuld=.bruchteile(anteil),berichtigungsbetrag_teilhaberschuld=.bruchteile(berichtigung),verbleibender_einzelanteil=.bruchteile(.subtrahieren(anteil,berichtigung)),ungedeckte_teilhaberschuld=.bruchteile(.subtrahieren(eigen,berichtigung)),ungedeckte_gemeinsame_schuld=.bruchteile(positiv(.subtrahieren(gemeinsam,erloes))))
 eingaben <- list(gemeinschaftlicher_erloes=gemeinschaftlicher_erloes,zu_berichtigende_gemeinsame_schulden=zu_berichtigende_gemeinsame_schulden,teilhaberquote=teilhaberquote,gemeinschaftsbezogene_teilhaberschuld=gemeinschaftsbezogene_teilhaberschuld,einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .ergebnis(wert,'EUR','BGB_GEMEINSCHAFT_AUFHEBUNGSANTEIL',eingaben,list(list(operation='Positive Erl\u00f6smasse nach gemeinsamen Schulden mit Quote multiplizieren; qualifizierte Teilhaberschuld h\u00f6chstens bis zu diesem Anteil berichtigen.')),eingaben)
 ergebnis$hinweise <- list("Nur \u00a7\u00a7753/755/756 bei rechtlich qualifizierter Erl\u00f6saufteilung. Gemeinsame Schuld muss \u00a7755 erf\u00fcllen und ihre Berichtigung verlangt sein; individuelle Schuld muss gemeinschaftsbezogener Anspruch eines anderen Teilhabers nach \u00a7756 sein und ihre Berichtigung verlangt sein. Betr\u00e4ge auf gleiche Abrechnung beziehen, keine Doppelz\u00e4hlung bereits abgezogener Kosten/Schulden. Einzelanteil des Schuldner-Teilhabers; Berichtigungsbetrag ist dem qualifizierten Gl\u00e4ubiger zus\u00e4tzlich zu dessen eigenem Erl\u00f6santeil zuzuordnen. Mehrere konkurrierende Forderungen, wechselseitige Forderungsnetze und Vorr\u00e4nge zuvor rechtlich bestimmen, nicht unbesehen saldieren. Ungedeckte gemeinsame Schuld ist Gesamtrest, keine automatische pers\u00f6nliche Quote. Keine Wertbewertung, Naturteilung/Losentscheidung oder zus\u00e4tzliche Haftungsentscheidung.")
 ergebnis
}
